"""Crawlable court summaries, separated from unreviewed opinion search matches."""
from datetime import datetime
from html import escape
from zoneinfo import ZoneInfo


def date_label(value):
    return datetime.fromisoformat(value).strftime('%b %d, %Y').replace(' 0',' ')


def ruling_card(item):
    checked = item['reviewState'] == 'Source checked'
    topics = item.get('topics', [])
    kind = item.get('kind', 'Relevance not yet reviewed')
    searchable = ' '.join([item['name'], item['court'], item.get('docket',''), *topics, item.get('summary',''), item.get('excerpt','')])
    badges = ''.join('<span class="news-badge">'+escape(value)+'</span>' for value in [item['group'], kind])
    tags = ''.join('<span>'+escape(topic)+'</span>' for topic in topics)
    summary = '<p class="ruling-summary">'+escape(item['summary'])+'</p>' if checked else '<p class="ruling-match-label">Automatically found opinion · relevance and holding not yet reviewed</p><p class="ruling-summary">This opinion matched a religious-liberty search in a monitored court.  The excerpt below is a search result, not a summary of the holding.</p><blockquote>'+escape(item.get('excerpt') or 'The feed did not provide an excerpt.  Read the linked opinion.')+'</blockquote>'
    note = '<p class="ruling-status"><strong>Procedural context:</strong> '+escape(item['statusNote'])+'</p>' if item.get('statusNote') else ''
    related = '<a href="'+escape(item['relatedUrl'],quote=True)+'" target="_blank" rel="noopener">Later order ↗</a>' if item.get('relatedUrl') else ''
    review_date = 'Sources checked '+date_label(item['checkedAt']) if checked else 'Discovered '+date_label(item['firstSeenAt'])
    return f'''<article class="news-card ruling-card" id="{item['id']}" data-ruling data-review="{'checked' if checked else 'match'}" data-group="{escape(item['group'],quote=True)}" data-state="{item['state']}" data-kind="{escape(kind,quote=True)}" data-date="{item['date']}" data-topics="{escape('|'.join(topics),quote=True)}" data-search="{escape(searchable,quote=True)}" {'' if checked else 'hidden'}><div class="news-meta">{badges}<time datetime="{item['date']}">{date_label(item['date'])}</time></div><h2><a href="{escape(item['sourceUrl'],quote=True)}" target="_blank" rel="noopener">{escape(item['name'])}</a></h2><p class="ruling-court">{escape(item['court'])}{' · '+escape(item['docket']) if item.get('docket') else ''}</p>{summary}{note}<div class="ruling-topics">{tags}</div><div class="news-source"><span>{review_date}</span><div class="ruling-links"><a href="{escape(item['sourceUrl'],quote=True)}" target="_blank" rel="noopener">{escape(item['sourceLabel'])} ↗</a>{related}<a href="#{item['id']}" aria-label="Link to this case entry">#</a></div></div></article>'''


def ruling_page(home, data, shell):
    rulings, matches = data['rulings'], data['matches']
    checked = datetime.fromisoformat(data['updatedAt']).astimezone(ZoneInfo('America/Chicago')).strftime('%b %d, %Y · %I:%M %p %Z').replace(' 0',' ') if data.get('updatedAt') else 'No successful feed check yet'
    warning = '<p class="news-warning">One or more opinion feeds could not be refreshed.  Earlier records are retained.  See feed status below.</p>' if data['status']!='ok' else ''
    limited = any(source.get('possiblyLimited') for source in data['sources'])
    if limited: warning += '<p class="news-warning">At least one feed reached its result limit.  The look-back is a researched starting collection, not a complete inventory of every ruling.</p>'
    def options(values):
        return ''.join('<option>'+escape(value)+'</option>' for value in sorted(set(values)))
    kinds = options(item['kind'] for item in rulings)
    topics = options(topic for item in rulings for topic in item['topics'])
    source_rows = ''.join('<li><a href="'+escape(source['url'],quote=True)+'" target="_blank" rel="noopener">'+escape(source['label'])+' ↗</a><span>'+('Checked successfully · '+str(source['count'])+' matching opinions returned'+(' · result limit may apply' if source.get('possiblyLimited') else '') if source['status']=='ok' else 'Refresh unavailable; prior records retained')+'</span></li>' for source in data['sources'])
    cards = ''.join(ruling_card(item) for item in [*rulings,*matches])
    content = f'''<section class="news-hero"><div><p class="eyebrow">THE COURTS · RELIGIOUS LIBERTY WATCH</p><h1>Court rulings.</h1><p>Religious liberty decisions from the U.S. Supreme Court, the Fifth Circuit, and state and federal courts in Texas, Louisiana, and Mississippi.  Read the ruling, understand its posture, and follow new opinions.</p></div><span class="news-hero-mark" aria-hidden="true">§</span></section><div class="news-freshness"><span class="source-dot"></span><span>Opinion feeds checked {checked}</span><span>·</span><span>Scheduled daily</span></div>{warning}<p id="ruling-stale" class="news-warning" data-updated="{escape(data.get('updatedAt') or '',quote=True)}" hidden>The opinion-feed snapshot is more than 36 hours old.  Check the linked sources for new rulings.</p><section class="stats" aria-label="Court watch totals"><div class="stat"><div class="stat-label">Case blurbs</div><div class="stat-number">{len(rulings)}</div><p>Source-checked opinions & orders</p></div><div class="stat"><div class="stat-label">New opinion matches</div><div class="stat-number">{len(matches)}</div><p>Separate queue awaiting review</p></div><div class="stat stat-watch"><div class="stat-label">Rolling look-back</div><div class="stat-number">180 <small>days</small></div><p>{date_label(data['windowStart'])} to {date_label(data['windowEnd'])}</p></div></section>
<nav class="news-tabs ruling-tabs" aria-label="Court record review status"><button class="news-tab selected" id="ruling-checked" aria-pressed="true">Case blurbs ({len(rulings)})</button><button class="news-tab" id="ruling-matches" aria-pressed="false">Opinion matches ({len(matches)})</button></nav><p class="hearing-tip" id="ruling-view-note">Case blurbs are checked against the linked decisions.  Procedural orders and related civil-remedies decisions are identified separately.</p>
<section class="hearing-filter-panel ruling-filters" data-window-end="{data['windowEnd']}"><label>Search<input id="ruling-search" type="search" placeholder="Case, docket, issue, or court…"></label><label>Court<select id="ruling-group"><option value="">All courts</option><option>U.S. Supreme Court</option><option>Fifth Circuit</option><option>Federal district</option><option>State court</option></select></label><label>Location<select id="ruling-state"><option value="">All locations</option><option>Texas</option><option>Louisiana</option><option>Mississippi</option><option value="Regional">Fifth Circuit region</option><option value="National">U.S. Supreme Court</option></select></label><label>Topic<select id="ruling-topic"><option value="">All topics</option>{topics}</select></label><label>Date<select id="ruling-period"><option value="">Past 180 days</option><option value="30">Past 30 days</option><option value="90">Past 90 days</option></select></label><label>Ruling type<select id="ruling-kind"><option value="">All types</option>{kinds}</select></label><button class="button" id="ruling-export">Export CSV ↓</button><button class="text-button" id="ruling-reset">Reset filters</button></section><p class="news-count" id="ruling-count" aria-live="polite">{len(rulings)} source-checked entries</p><div class="news-list">{cards}</div><section class="content-card" id="ruling-empty" hidden><h2>No entries match this view.</h2><p>Try another court, topic, or the opinion-matches view.  An empty result does not mean no relevant ruling exists.</p></section>
<section class="news-method content-card"><h2>How the court watch works</h2><p>The initial look-back covers May 15 through November 11, 2026.  The displayed collection then rolls forward over 180 days.  The case blurbs were checked against court opinions, filed orders, and official dockets; each entry identifies its source and review date.  Summaries distinguish allegations from findings, merits decisions from procedural rulings, and later stays where verified.</p><p>Daily checks search CourtListener’s public opinion feeds for religious liberty, free exercise, church autonomy, religious discrimination and accommodation, RFRA, RLUIPA, the Establishment Clause, and the ministerial exception.  New matches appear automatically under “Opinion matches,” with attributed excerpts.  Keyword matches can be incidental; they are not promoted automatically into source-checked holdings or attributed to Eric Hudson as reviewed analysis.</p><p>Coverage includes the U.S. Supreme Court, the Fifth Circuit, federal district courts in Texas, Louisiana, and Mississippi, and indexed state-court opinions in those three states.  Public feed coverage is uneven, especially for trial-court and emergency orders.  The initial research found no source-checked Louisiana state or federal district entry for this window; that is a coverage gap, not a conclusion that none exists.  This service is not a complete docket search, citator, or automatic appeal-status check.  A daily feed check does not reverify every older case’s current validity.</p><details><summary>Opinion feeds & update status</summary><ul>{source_rows}</ul><p>Existing discovered matches are retained within the rolling window if a feed fails or a result drops out of its limited feed.  Source-checked blurbs are maintained separately.  The daily schedule continues after the Texas 90R legislative session.</p><a href="https://wiki.free.law/c/courtlistener/help/general/using-atom-and-rss-feeds-for-the-latest-updates" target="_blank" rel="noopener">About CourtListener’s public feeds ↗</a></details></section><script src="/rulings.js" defer></script>'''
    return shell(home, 'Religious liberty court rulings | Supreme Court & Fifth Circuit', 'Track religious liberty court rulings, case summaries, and daily opinion matches from the U.S. Supreme Court and Texas, Louisiana, and Mississippi courts.', '/rulings/', content)
